//! Versioned, self-contained replays. CPU intents are generated by the deterministic sim.
use crate::{
    Screen,
    input::Devices,
    play::{self, Match, Mode, Rules, Slot},
    ui::{self, *},
};
use bevy::prelude::*;
use serde::{Deserialize, Serialize};
use sim::{GameData, Input, MatchConfig, World, step_world};
use std::{
    fs,
    path::{Path, PathBuf},
    sync::Arc,
    time::{SystemTime, UNIX_EPOCH},
};

#[derive(Clone, Serialize, Deserialize)]
pub struct Run {
    ticks: u64,
    inputs: Vec<Input>,
}
#[derive(Clone, Serialize, Deserialize)]
pub struct Replay {
    version: u32,
    created: u64,
    #[serde(with = "content")]
    pub data: GameData,
    pub config: MatchConfig,
    runs: Vec<Run>,
    checksums: Vec<(u64, u64)>,
    pub ticks: u64,
    final_hash: u64,
}
fn checksum(w: &World) -> u64 {
    serde_json::to_vec(w)
        .expect("world serializes")
        .iter()
        .fold(0xcbf29ce484222325, |h, b| (h ^ u64::from(*b)).wrapping_mul(0x100000001b3))
}
fn drain(w: &mut World) {
    w.fx.clear();
    w.hits.clear();
}
impl Replay {
    pub fn new(data: &GameData, w: &World) -> Self {
        Self {
            version: 1,
            created: SystemTime::now().duration_since(UNIX_EPOCH).map_or(0, |d| d.as_secs()),
            data: data.clone(),
            config: w.cfg.clone(),
            runs: vec![],
            checksums: vec![(0, checksum(w))],
            ticks: 0,
            final_hash: checksum(w),
        }
    }
    pub fn record(&mut self, inputs: Vec<Input>, w: &World) {
        if let Some(last) = self.runs.last_mut().filter(|r| r.inputs == inputs) {
            last.ticks += 1;
        } else {
            self.runs.push(Run { ticks: 1, inputs });
        }
        self.ticks += 1;
        if self.ticks.is_multiple_of(self.data.global.replay.checkpoint_ticks.max(1)) {
            self.checksums.push((self.ticks, checksum(w)));
        }
        // Only recompute at checkpoints or the end of the match.
        if w.over {
            self.final_hash = checksum(w);
        }
    }
    fn read(path: &Path) -> Result<Self, String> {
        let r: Self = serde_json::from_slice(&fs::read(path).map_err(|e| e.to_string())?).map_err(|e| e.to_string())?;
        r.validate()?;
        Ok(r)
    }
    fn validate(&self) -> Result<(), String> {
        if self.version != 1 {
            return Err(format!("unsupported replay version {}", self.version));
        }
        if self.ticks == 0
            || self.runs.iter().any(|r| r.ticks == 0 || r.inputs.len() != self.config.players.len())
            || self.runs.iter().try_fold(0u64, |n, r| n.checked_add(r.ticks)) != Some(self.ticks)
        {
            return Err("invalid replay input stream".into());
        }
        let interval = self.data.global.replay.checkpoint_ticks.max(1);
        if self.checksums.len() as u64 != self.ticks / interval + 1
            || self.checksums.iter().enumerate().any(|(i, (tick, _))| *tick != i as u64 * interval)
        {
            return Err("invalid replay checksum stream".into());
        }
        Ok(())
    }
    pub fn save(&self, automatic: bool) -> Result<PathBuf, String> {
        let dir = directory().ok_or("platform data directory unavailable")?;
        fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
        let name =
            format!("{}-{}-{}.replay.json", if automatic { "auto" } else { "saved" }, self.created, self.config.seed);
        let path = dir.join(name);
        let tmp = path.with_extension("tmp");
        fs::write(&tmp, serde_json::to_vec(self).map_err(|e| e.to_string())?).map_err(|e| e.to_string())?;
        fs::rename(tmp, &path).map_err(|e| e.to_string())?;
        if automatic {
            let mut files: Vec<_> = paths(&dir)
                .into_iter()
                .filter(|p| p.file_name().is_some_and(|n| n.to_string_lossy().starts_with("auto-")))
                .collect();
            files.sort();
            let remove = files.len().saturating_sub(self.data.global.replay.auto_save_count);
            for p in files.into_iter().take(remove) {
                fs::remove_file(p).map_err(|e| e.to_string())?;
            }
        }
        Ok(path)
    }
}
fn directory() -> Option<PathBuf> {
    dirs::data_dir().map(|p| p.join("stick-smash/replays"))
}
fn paths(dir: &Path) -> Vec<PathBuf> {
    let mut paths: Vec<_> = fs::read_dir(dir)
        .into_iter()
        .flatten()
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.to_string_lossy().ends_with(".replay.json"))
        .collect();
    paths.sort();
    paths.reverse();
    paths
}

pub struct Playback {
    pub replay: Replay,
    snapshots: Vec<(u64, World)>,
    run: usize,
    offset: u64,
    pub position: u64,
    pub warning: Option<String>,
    pub hide_hud: bool,
    cursor: Cursor,
}
impl Playback {
    pub fn new(replay: Replay) -> Result<Self, String> {
        replay.validate()?;
        let w = World::new(replay.config.clone(), &replay.data)?;
        let mut p = Self {
            replay,
            snapshots: vec![(0, w.clone())],
            run: 0,
            offset: 0,
            position: 0,
            warning: None,
            hide_hud: false,
            cursor: Cursor { key: 1, owner: None },
        };
        p.verify(&w);
        Ok(p)
    }
    fn verify(&mut self, w: &World) {
        let expected = self
            .replay
            .checksums
            .iter()
            .find(|(t, _)| *t == self.position)
            .map(|(_, h)| *h)
            .or_else(|| (self.position == self.replay.ticks).then_some(self.replay.final_hash));
        if expected.is_some_and(|h| h != checksum(w)) && self.warning.is_none() {
            self.warning = Some(format!("Replay desync at tick {}: simulation differs from recording", self.position));
        }
    }
    pub fn inputs(&mut self) -> Option<Vec<Input>> {
        let r = self.replay.runs.get(self.run)?;
        let inputs = r.inputs.clone();
        self.offset += 1;
        if self.offset == r.ticks {
            self.offset = 0;
            self.run += 1;
        }
        self.position += 1;
        Some(inputs)
    }
    pub fn after_tick(&mut self, w: &World) {
        self.verify(w);
        if self.position.is_multiple_of(self.replay.data.global.replay.checkpoint_ticks.max(1))
            && self.snapshots.last().is_none_or(|(t, _)| *t < self.position)
        {
            self.snapshots.push((self.position, w.clone()));
        }
    }
    pub fn seek(&mut self, target: u64, w: &mut World) {
        let target = target.min(self.replay.ticks);
        let (tick, snapshot) = self.snapshots.iter().rev().find(|(t, _)| *t <= target).unwrap();
        *w = snapshot.clone();
        self.position = *tick;
        self.run = 0;
        self.offset = *tick;
        while self.run < self.replay.runs.len() && self.offset >= self.replay.runs[self.run].ticks {
            self.offset -= self.replay.runs[self.run].ticks;
            self.run += 1;
        }
        while self.position < target {
            let inputs = self.inputs().unwrap();
            step_world(w, &self.replay.data, &inputs);
            drain(w);
            self.after_tick(w);
        }
    }
}
pub fn start(
    r: Replay,
    commands: &mut Commands,
    scene: &mut render::Scene,
    next: &mut NextState<Screen>,
) -> Result<(), String> {
    let p = Playback::new(r)?;
    let data = Arc::new(p.replay.data.clone());
    let cfg = &p.replay.config;
    let slots = cfg
        .players
        .iter()
        .enumerate()
        .map(|(i, c)| Slot {
            dev: None,
            fighter: data.fighters.iter().position(|f| f.id == c.fighter).unwrap(),
            cpu: c.cpu,
            team: c.team,
            tap_jump: c.tap_jump,
            tag: format!("P{}", i + 1),
            color: i,
        })
        .collect();
    let mut m = Match::new(
        &data,
        Mode::Replay,
        slots,
        Rules { stocks: cfg.stocks, stage: cfg.stage.clone(), friendly_fire: cfg.friendly_fire },
        cfg.seed,
    )?;
    m.data = data;
    m.world = p.snapshots[0].1.clone();
    m.playback = Some(p);
    play::install(commands, scene, m);
    next.set(Screen::Playback);
    Ok(())
}
pub fn verify_directory(dir: &Path) -> Result<(), String> {
    let files = paths(dir);
    if files.is_empty() {
        return Err(format!("no .replay.json files in {}", dir.display()));
    }
    for file in files {
        let mut p = Playback::new(Replay::read(&file)?)?;
        let mut w = p.snapshots[0].1.clone();
        p.seek(p.replay.ticks, &mut w);
        if let Some(e) = p.warning {
            return Err(format!("{}: {e}", file.display()));
        }
        if !w.over {
            return Err(format!("{}: unfinished match", file.display()));
        }
        println!("{}: verified {} ticks, winner {:?}", file.display(), p.position, w.winner);
    }
    Ok(())
}

#[derive(Resource, Default)]
pub struct Library {
    cursor: Cursor,
    entries: Vec<(PathBuf, String)>,
    warning: String,
    page: usize,
}
#[derive(Component)]
pub struct LibraryRoot(String);
pub fn enter(mut lib: ResMut<Library>) {
    lib.cursor = Cursor { key: 1, owner: None };
    lib.warning.clear();
    lib.page = 0;
    lib.entries = directory()
        .map(|d| paths(&d))
        .unwrap_or_default()
        .into_iter()
        .map(|p| {
            let label = match Replay::read(&p) {
                Ok(r) => format!(
                    "{} · {} · {}",
                    date(r.created),
                    r.config.stage,
                    r.config.players.iter().map(|p| p.fighter.as_str()).collect::<Vec<_>>().join(" / ")
                ),
                Err(e) => format!("Unreadable: {e}"),
            };
            (p, label)
        })
        .collect();
}
// Gregorian date from days since Unix epoch, independent of local timezone.
fn date(seconds: u64) -> String {
    let z = (seconds / 86400) as i64 + 719468;
    let era = z / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = mp + if mp < 10 { 3 } else { -9 };
    format!(
        "{:04}-{month:02}-{day:02} {:02}:{:02} UTC",
        y + i64::from(month <= 2),
        seconds / 3600 % 24,
        seconds / 60 % 60
    )
}
#[allow(clippy::too_many_arguments)]
pub fn library(
    mut commands: Commands,
    mut lib: ResMut<Library>,
    devs: Res<Devices>,
    q: FocusQuery,
    fonts: Res<Fonts>,
    roots: Query<(Entity, &LibraryRoot)>,
    mut scene: ResMut<render::Scene>,
    mut next: ResMut<NextState<Screen>>,
) {
    for (_, nav) in devs.navs() {
        let spots = ui::spots(&q);
        match lib.cursor.drive(nav, &spots) {
            Some(Action::Back | Action::Activate(0)) => next.set(Screen::Title),
            Some(Action::Activate(u32::MAX)) => {
                lib.page = lib.page.saturating_sub(1);
                lib.cursor.key = 0;
            }
            Some(Action::Activate(k)) if k == u32::MAX - 1 => {
                lib.page += 1;
                lib.cursor.key = 0;
            }
            Some(Action::Activate(k)) => {
                if let Some((path, _)) = lib.entries.get(k as usize - 1)
                    && let Err(e) = Replay::read(path).and_then(|r| start(r, &mut commands, &mut scene, &mut next))
                {
                    lib.warning = e;
                }
            }
            _ => {}
        }
    }
    let signature = format!("{}:{}:{}", lib.cursor.key, lib.page, lib.warning);
    if roots.iter().any(|(_, r)| r.0 == signature) {
        return;
    }
    for (e, _) in &roots {
        commands.entity(e).despawn();
    }
    commands
        .spawn((
            root(),
            LibraryRoot(signature),
            DespawnOnExit(Screen::Replays),
            BackgroundColor(ui::NIGHT),
            GlobalZIndex(5),
        ))
        .with_children(|p| {
            p.spawn(node(|n| {
                n.flex_direction = FlexDirection::Column;
                n.padding = UiRect::all(Val::Px(40.));
                n.overflow = Overflow::scroll_y();
                n.height = Val::Percent(100.);
            }))
            .with_children(|p| {
                p.spawn(txt(&fonts.display, 64., STAR, "Replays"));
                p.spawn(txt(
                    &fonts.body,
                    18.,
                    DIM,
                    if lib.entries.is_empty() { "No saved replays" } else { &lib.warning },
                ));
                let mut items: Vec<_> = lib
                    .entries
                    .iter()
                    .enumerate()
                    .skip(lib.page * 8)
                    .take(8)
                    .map(|(i, (_, label))| Item::button(i as u32 + 1, label))
                    .collect();
                if lib.page > 0 {
                    items.push(Item::button(u32::MAX, "Previous page"));
                }
                if (lib.page + 1) * 8 < lib.entries.len() {
                    items.push(Item::button(u32::MAX - 1, "Next page"));
                }
                items.push(Item::button(0, "Back"));
                menu_list(p, &fonts, &items, lib.cursor.key, 1150., 22.);
            });
        });
}
#[derive(Component)]
pub struct ControlsRoot(String);
#[derive(Component)]
pub struct SeekBar;
#[derive(Component)]
pub struct SeekFill;
#[derive(Component)]
pub struct PositionText;

#[allow(clippy::too_many_arguments, clippy::type_complexity)]
pub fn controls(
    mut commands: Commands,
    mut m: ResMut<Match>,
    mut scene: ResMut<render::Scene>,
    mut next: ResMut<NextState<Screen>>,
    devs: Res<Devices>,
    q: FocusQuery,
    fonts: Res<Fonts>,
    roots: Query<(Entity, &ControlsRoot)>,
    mut hud: Query<&mut Node, With<crate::hud::HudRoot>>,
    bars: Query<&bevy::ui::RelativeCursorPosition, With<SeekBar>>,
    mouse: Res<ButtonInput<MouseButton>>,
    mut fills: Query<&mut Node, (With<SeekFill>, Without<crate::hud::HudRoot>)>,
    mut positions: Query<&mut Text, With<PositionText>>,
) {
    let m = &mut *m;
    let Some(p) = m.playback.as_mut() else { return };
    let mut seek = None;
    let spots = ui::spots(&q);
    for (_, nav) in devs.navs() {
        match p.cursor.drive(nav, &spots) {
            Some(Action::Activate(1) | Action::Start) => m.frozen = !m.frozen,
            Some(Action::Activate(2)) => {
                m.frozen = true;
                m.step = true;
            }
            Some(Action::Spin(3, by)) => {
                let speeds = [0.25, 0.5, 1., 2.];
                let i = speeds.iter().position(|s| *s == m.speed).unwrap_or(2);
                m.speed = speeds[(i as i32 + by).rem_euclid(4) as usize];
            }
            Some(Action::Activate(4)) => p.hide_hud = !p.hide_hud,
            Some(Action::Back | Action::Activate(5)) => next.set(Screen::Replays),
            Some(Action::Spin(6, by)) => {
                seek =
                    Some(p.position.saturating_add_signed(i64::from(by) * i64::from(sim::TICK_HZ)).min(p.replay.ticks))
            }
            _ => {}
        }
    }
    for cursor in &bars {
        if mouse.pressed(MouseButton::Left)
            && cursor.cursor_over
            && let Some(pos) = cursor.normalized
        {
            seek = Some((f64::from(pos.x.clamp(0., 1.)) * p.replay.ticks as f64).round() as u64);
        }
    }
    if let Some(tick) = seek {
        p.seek(tick, &mut m.world);
        m.sounds.clear();
        scene.reset(&m.world);
    }
    for mut node in &mut hud {
        node.display = if p.hide_hud { Display::None } else { Display::Flex };
    }
    for mut fill in &mut fills {
        fill.width = Val::Percent(100. * p.position as f32 / p.replay.ticks.max(1) as f32);
    }
    for mut text in &mut positions {
        text.0 = format!("Tick {} / {} · seek: left / right or drag bar", p.position, p.replay.ticks);
    }
    let sig = format!("{}:{}:{}:{}:{:?}", p.cursor.key, m.frozen, m.speed, p.hide_hud, p.warning);
    if roots.iter().any(|(_, r)| r.0 == sig) {
        return;
    }
    for (e, _) in &roots {
        commands.entity(e).despawn();
    }
    commands
        .spawn((
            node(|n| {
                n.position_type = PositionType::Absolute;
                n.top = Val::Px(12.);
                n.left = Val::Percent(3.);
                n.width = Val::Percent(94.);
                n.flex_direction = FlexDirection::Column;
                n.padding = UiRect::all(Val::Px(12.));
                n.border_radius = BorderRadius::all(Val::Px(8.));
            }),
            ControlsRoot(sig),
            DespawnOnExit(Screen::Playback),
            GlobalZIndex(10),
            BackgroundColor(ui::INK),
        ))
        .with_children(|parent| {
            parent.spawn(row()).with_children(|row| {
                for item in [
                    Item::button(1, if m.frozen { "Play" } else { "Pause" }),
                    Item::button(2, "Frame step"),
                    Item::spin(3, "Speed", format!("{}×", m.speed)),
                    Item::button(4, if p.hide_hud { "Show HUD" } else { "Hide HUD" }),
                    Item::button(5, "Replays"),
                ] {
                    menu_list(row, &fonts, &[item], p.cursor.key, 220., 22.);
                }
            });
            parent.spawn((
                txt(
                    &fonts.body,
                    16.,
                    DIM,
                    format!("Tick {} / {} · seek: left / right or drag bar", p.position, p.replay.ticks),
                ),
                PositionText,
            ));
            parent
                .spawn((
                    node(|n| {
                        n.width = Val::Percent(100.);
                        n.height = Val::Px(20.);
                        n.margin.top = Val::Px(6.);
                    }),
                    SeekBar,
                    bevy::ui::RelativeCursorPosition::default(),
                    BackgroundColor(ui::LINE),
                    Focusable { key: 6, owner: None, spin: true },
                ))
                .with_children(|bar| {
                    bar.spawn((
                        node(|n| {
                            n.width = Val::Percent(100. * p.position as f32 / p.replay.ticks.max(1) as f32);
                            n.height = Val::Percent(100.);
                        }),
                        SeekFill,
                        BackgroundColor(if p.cursor.key == 6 { ui::GOLD } else { ui::DIM }),
                    ));
                });
            if let Some(e) = &p.warning {
                parent.spawn(txt(&fonts.heavy, 20., Color::srgb(1., 0.3, 0.3), e));
            }
        });
}

mod content {
    use super::*;
    pub fn serialize<S: serde::Serializer>(data: &GameData, s: S) -> Result<S::Ok, S::Error> {
        (
            data,
            data.fighters.iter().map(|f| &f.id).collect::<Vec<_>>(),
            data.stages.iter().map(|s| &s.id).collect::<Vec<_>>(),
        )
            .serialize(s)
    }
    pub fn deserialize<'de, D: serde::Deserializer<'de>>(d: D) -> Result<GameData, D::Error> {
        let (mut data, fighters, stages): (GameData, Vec<String>, Vec<String>) = Deserialize::deserialize(d)?;
        if data.fighters.len() != fighters.len() || data.stages.len() != stages.len() {
            return Err(serde::de::Error::custom("invalid content ids"));
        }
        for (f, id) in data.fighters.iter_mut().zip(fighters) {
            f.id = id;
        }
        for (s, id) in data.stages.iter_mut().zip(stages) {
            s.id = id;
        }
        Ok(data)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    fn recorded() -> (Replay, World) {
        let (data, errors) = crate::load_data(&[PathBuf::from("../../assets")]);
        assert!(errors.is_empty());
        let cfg = MatchConfig {
            stocks: 1,
            seed: 7,
            players: vec![
                sim::PlayerConfig { cpu: Some(2), ..sim::PlayerConfig::human("brawler") },
                sim::PlayerConfig { cpu: Some(2), ..sim::PlayerConfig::human("king") },
            ],
            ..default()
        };
        let mut w = World::new(cfg, &data).unwrap();
        let mut r = Replay::new(&data, &w);
        while !w.over && w.frame < 36000 {
            let inputs = vec![Input::default(); 2];
            step_world(&mut w, &data, &inputs);
            drain(&mut w);
            r.record(inputs, &w);
        }
        assert!(w.over);
        (r, w)
    }
    #[test]
    fn cpu_match_round_trip_checksums_outcome_and_seek() {
        let (r, expected) = recorded();
        let encoded = serde_json::to_vec(&r).unwrap();
        let dir = std::env::temp_dir().join(format!("stick-smash-replay-test-{}", std::process::id()));
        fs::create_dir_all(&dir).unwrap();
        let file = dir.join("cpu.replay.json");
        fs::write(&file, encoded).unwrap();
        let r = Replay::read(&file).unwrap();
        verify_directory(&dir).unwrap();
        fs::remove_dir_all(&dir).unwrap();
        assert_eq!(r.runs.len(), 1, "CPU inputs compress to one run");
        let mut p = Playback::new(r).unwrap();
        let mut w = p.snapshots[0].1.clone();
        p.seek(p.replay.ticks, &mut w);
        assert_eq!(p.warning, None);
        assert_eq!(w, expected);
        p.seek(450, &mut w);
        p.seek(1200.min(p.replay.ticks), &mut w);
        p.seek(p.replay.ticks, &mut w);
        assert_eq!(w, expected);
        assert_eq!(p.warning, None);
    }
    #[test]
    fn detects_changed_simulation_and_unsupported_format() {
        let (mut r, _) = recorded();
        for f in &mut r.data.fighters {
            f.stats.run_speed *= 0.5;
        }
        let mut p = Playback::new(r.clone()).unwrap();
        let mut w = p.snapshots[0].1.clone();
        p.seek(p.replay.ticks, &mut w);
        assert!(p.warning.is_some());
        assert!(!p.warning.as_ref().unwrap().contains("tick 0:"));
        r.version = 99;
        assert!(Playback::new(r).is_err());
    }
}
